{
    // EF Core 9 breaking change: synchronous I/O now throws by default.
    // Use async APIs throughout.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still references "Discriminator" which works
        // because we explicitly configured HasDiscriminator("Discriminator") in the model.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Migrated from sync .ToList() to async .ToListAsync()
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

